import 'dart:convert'; import 'package:http/http.dart' as http; import 'package:supabase_flutter/supabase_flutter.dart'; import 'email_agent_models.dart';
class EmailAgentRepository { EmailAgentRepository(this.baseUrl,this.client); final String baseUrl; final SupabaseClient client; Future<Map<String,String>> _headers()async{final token=client.auth.currentSession?.accessToken;if(token==null)throw Exception('Sign in required.');return {'Authorization':'Bearer $token','Content-Type':'application/json'};} Future<dynamic> _call(String path,{String method='GET',Map<String,dynamic>? body})async{final url=Uri.parse('$baseUrl$path');final headers=await _headers();final response=method=='POST'?await http.post(url,headers:headers,body:jsonEncode(body??{})):method=='PATCH'?await http.patch(url,headers:headers,body:jsonEncode(body??{})):await http.get(url,headers:headers);if(response.statusCode>=400)throw Exception('Email Agent request failed.');return jsonDecode(response.body);} Future<EmailAgentState> state()async=>EmailAgentState.fromJson(Map<String,dynamic>.from(await _call('/api/v1/agents/email'))); Future<void> setStatus(String status)async{await _call('/api/v1/agents/email/status',method:'POST',body:{'status':status});} Future<EmailAgentPolicy> policy()async=>EmailAgentPolicy.fromJson(Map<String,dynamic>.from((await _call('/api/v1/agents/email/policy'))['policy']??{})); Future<void> updatePolicy(EmailAgentPolicy policy)async{await _call('/api/v1/agents/email/policy',method:'PATCH',body:policy.toJson());} Future<EmailManualRunResult> run()async=>EmailManualRunResult.fromJson(Map<String,dynamic>.from(await _call('/api/v1/agents/email/run',method:'POST'))); }
